const __pageData = JSON.parse('{"title":"RabbitMQ 可靠投递：Confirm、Return 与消费幂等","description":"","frontmatter":{"title":"RabbitMQ 可靠投递：Confirm、Return 与消费幂等","date":"2026-08-04T00:00:00.000Z","category":"MQ","cover":"/covers/backend.svg","tags":["rabbitmq","spring-amqp","message-queue"],"excerpt":"从生产者 Confirm、mandatory Return、消费确认到 Outbox 与幂等表，建立 RabbitMQ 端到端至少一次投递链路。"},"headers":[],"relativePath":"posts/rabbitmq-reliable-delivery.md","filePath":"posts/rabbitmq-reliable-delivery.md","lastUpdated":1787128073000}');
